  if(!v){
    try{ s=String(MY_URL||''); }catch(e2){}
    m=s.match(/[?？&]vid=(\d+)/);
    if(m) v=parseInt(m[1],10)||0;
  }
  if(!v){ try{ v=parseInt((MY_PARAMS&&MY_PARAMS.vid)||0,10)||0; }catch(e3){} }
  return v;
}
