  try{ if(typeof MY_PARAMS!=='undefined'&&MY_PARAMS){ cands.push(MY_PARAMS.t||''); cands.push(MY_PARAMS.fyclass||''); } }catch(e3){}
  for(var i=0;i<cands.length;i++){
    var v=String(cands[i]==null?'':cands[i]);
